  animation: salesGapGrow 150ms ease-out;
}
tr.sales-board-row {
  transform-origin: 50% 50%;
  transition: transform 170ms cubic-bezier(0.22, 1.1, 0.36, 1),
    box-shadow 170ms ease, background-color 120ms ease;
}
tr.sales-focus-row {
  position: relative;
  z-index: 5;
  background: linear-gradient(180deg, #eff6ff 0%, #dbeafe 100%);
  box-shadow: 0 14px 34px -12px rgba(37, 99, 235, 0.55),
    0 0 0 2px rgba(59, 130, 246, 0.9);
}
tr.sales-focus-row > td {
  padding-top: 10px;
  padding-bottom: 10px;
  font-size: 14px;
  transition: padding-top 150ms ease, padding-bottom 150ms ease, font-size 150ms ease;
}
tr.sales-focus-row > td :where(*) {
  font-size: inherit;
}
.sales-focus-num {
  background: linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%);
  box-shadow: inset 0 0 0 1.5px rgba(255, 255, 255, 0.6);
}
@media (prefers-reduced-motion: reduce) {
  tr.sales-board-row { transition: none; }
  .sales-focus-gap-inner { animation: none; }
}

