/* ?????? Ambient surfaces & status glows ????????????????????????????????????????????????????????????????????????????????????????????????????????? */
@keyframes ambientDrift {
  0% { background-position: 0% 40%; }
  50% { background-position: 100% 60%; }
  100% { background-position: 0% 40%; }
}
.ambient-mesh {
  background-image:
    radial-gradient(at 18% 22%, rgba(99, 102, 241, 0.28) 0, transparent 55%),
    radial-gradient(at 82% 18%, rgba(34, 211, 238, 0.22) 0, transparent 55%),
    radial-gradient(at 55% 85%, rgba(168, 85, 247, 0.20) 0, transparent 60%);
  background-size: 200% 200%;
  animation: ambientDrift 22s ease-in-out infinite;
}
.dark .ambient-mesh {
  background-image:
    radial-gradient(at 18% 22%, rgba(99, 102, 241, 0.35) 0, transparent 55%),
    radial-gradient(at 82% 18%, rgba(34, 211, 238, 0.26) 0, transparent 55%),
    radial-gradient(at 55% 85%, rgba(168, 85, 247, 0.24) 0, transparent 60%);
}

.glow-card {
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06), 0 8px 24px -12px rgba(15, 23, 42, 0.18);
  transition: box-shadow 280ms ease, transform 280ms ease;
}
.glow-card:hover {
  box-shadow: 0 2px 4px rgba(15, 23, 42, 0.08), 0 16px 40px -14px rgba(15, 23, 42, 0.28);
}
.glow-success {
  border-color: rgba(34, 197, 94, 0.45) !important;
  box-shadow: 0 0 0 1px rgba(34, 197, 94, 0.12), 0 10px 30px -10px rgba(34, 197, 94, 0.35);
}
.glow-warning {
  border-color: rgba(245, 158, 11, 0.45) !important;
  box-shadow: 0 0 0 1px rgba(245, 158, 11, 0.12), 0 10px 30px -10px rgba(245, 158, 11, 0.35);
}
.glow-danger {
  border-color: rgba(239, 68, 68, 0.45) !important;
  box-shadow: 0 0 0 1px rgba(239, 68, 68, 0.12), 0 10px 30px -10px rgba(239, 68, 68, 0.35);
}
.glow-info {
  border-color: rgba(59, 130, 246, 0.45) !important;
  box-shadow: 0 0 0 1px rgba(59, 130, 246, 0.12), 0 10px 30px -10px rgba(59, 130, 246, 0.35);
}

@media (prefers-reduced-motion: reduce) {
  .ambient-mesh { animation: none; }
}

/* ?????? Face-scan reticle (Time Clock kiosk) ?????????????????????????????????????????????????????????????????????????????????????????? */
@keyframes scanSweep {
  0%   { top: 6%;  opacity: 0; }
  10%  { opacity: 0.9; }
  90%  { opacity: 0.9; }
  100% { top: 92%; opacity: 0; }
}
@keyframes scanBreath {
  0%, 100% { transform: scale(1);     opacity: 0.55; }
  50%      { transform: scale(1.05);  opacity: 0.95; }
}
@keyframes successRing {
  0%   { transform: scale(0.65); opacity: 1; }
  100% { transform: scale(1.6);  opacity: 0; }
}
@keyframes drawCheck {
  to { stroke-dashoffset: 0; }
}
.scan-reticle { position: absolute; inset: 0; pointer-events: none; }
.scan-bracket {
  position: absolute; width: 26px; height: 26px;
  border: 3px solid var(--scan-color, #818cf8);
  transition: border-color 300ms ease;
}
.scan-bracket.tl { top: 8px;    left: 8px;   border-right: 0;  border-bottom: 0; border-radius: 12px 0 0 0; }
.scan-bracket.tr { top: 8px;    right: 8px;  border-left: 0;   border-bottom: 0; border-radius: 0 12px 0 0; }
.scan-bracket.bl { bottom: 8px; left: 8px;   border-right: 0;  border-top: 0;    border-radius: 0 0 0 12px; }
.scan-bracket.br { bottom: 8px; right: 8px;  border-left: 0;   border-top: 0;    border-radius: 0 0 12px 0; }
.scan-oval {
  position: absolute; inset: 16% 24%;
  border: 2px solid var(--scan-color, #818cf8);
  border-radius: 50%;
  animation: scanBreath 2.1s ease-in-out infinite;
}
.scan-line {
  position: absolute; left: 8%; right: 8%; height: 2px;
  background: linear-gradient(90deg, transparent, var(--scan-color, #818cf8), transparent);
  box-shadow: 0 0 14px 2px var(--scan-color, #818cf8);
  animation: scanSweep 2.4s ease-in-out infinite;
}
.scan-tone-scanning  { --scan-color: #818cf8; }
.scan-tone-verifying { --scan-color: #fbbf24; }
.scan-tone-dim       { --scan-color: #f59e0b; }
.scan-tone-success   { --scan-color: #34d399; }
.success-burst {
  position: absolute; inset: 0;
  border: 3px solid #34d399; border-radius: 1rem;
  animation: successRing 700ms ease-out forwards;
  pointer-events: none;
}
.check-draw {
  stroke-dasharray: 34; stroke-dashoffset: 34;
  animation: drawCheck 450ms 150ms ease-out forwards;
}
@media (prefers-reduced-motion: reduce) {
  .scan-line, .scan-oval, .success-burst, .check-draw { animation: none !important; }
  .check-draw { stroke-dashoffset: 0; }
  .tracker-pulse, .tracker-flip, .tracker-today-bar, .tracker-glow, .tracker-breathe, .tracker-sweep::after, .tracker-blink, .tracker-roll, .tracker-celebrate, .punch-sheen, .crystal-sweep, .mci-time-pop { animation: none !important; }
}

/* Time Tracker pill animations */
@keyframes trackerPulse {
  0% { box-shadow: 0 0 0 0 rgba(99, 102, 241, 0.55); }
  70% { box-shadow: 0 0 0 10px rgba(99, 102, 241, 0); }
  100% { box-shadow: 0 0 0 0 rgba(99, 102, 241, 0); }
}
.tracker-pulse { animation: trackerPulse 1.2s ease-out 2; }
@keyframes trackerFlip {
  0% { transform: rotateX(90deg); opacity: 0; }
  100% { transform: rotateX(0deg); opacity: 1; }
}
.tracker-flip { animation: trackerFlip 320ms ease-out; transform-origin: 50% 100%; }
@keyframes trackerTodayBar {
  0%, 100% { filter: brightness(1); }
  50% { filter: brightness(1.18); }
}
.tracker-today-bar { animation: trackerTodayBar 2.4s ease-in-out infinite; }

@keyframes punchSheen {
  0% { transform: translateX(-160%) skewX(-16deg); }
  55%, 100% { transform: translateX(420%) skewX(-16deg); }
}
.punch-sheen {
  left: -10%;
  animation: punchSheen 3.4s ease-in-out infinite;
}

/* Crystal Shift ??? slower prismatic counter-sweep */
@keyframes crystalSweep {
  0%, 62% { transform: translateX(520%) skewX(-16deg); }
  100% { transform: translateX(-260%) skewX(-16deg); }
}
.crystal-sweep {
  left: -10%;
  animation: crystalSweep 6.8s ease-in-out infinite;
}

/* Missed Clock In dialog */
@keyframes mciTimePop {
  0% { transform: translateY(6px) scale(0.96); opacity: 0.35; }
  100% { transform: translateY(0) scale(1); opacity: 1; }
}
.mci-time-pop { animation: mciTimePop 180ms ease-out; }
.mci-slider {
  -webkit-appearance: none;
  appearance: none;
  height: 8px;
  border-radius: 9999px;
  background: linear-gradient(to right, #f59e0b var(--mci-fill, 0%), #e7e5e4 var(--mci-fill, 0%));
  outline: none;
  cursor: pointer;
}
.mci-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid #f59e0b;
  box-shadow: 0 1px 5px rgba(0, 0, 0, 0.3);
  cursor: grab;
  transition: transform 120ms ease;
}
.mci-slider::-webkit-slider-thumb:hover { transform: scale(1.12); }
.mci-slider:active::-webkit-slider-thumb { cursor: grabbing; transform: scale(1.18); }
.mci-slider::-moz-range-thumb {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid #f59e0b;
  box-shadow: 0 1px 5px rgba(0, 0, 0, 0.3);
  cursor: grab;
  transition: transform 120ms ease;
}
.mci-slider::-moz-range-thumb:hover { transform: scale(1.12); }
.mci-slider:active::-moz-range-thumb { cursor: grabbing; transform: scale(1.18); }
.mci-slider::-moz-range-track { background: transparent; }
@keyframes trackerGlow {
  0%, 100% { box-shadow: 0 0 0 0 rgba(99, 102, 241, 0); }
  50% { box-shadow: 0 0 14px 4px rgba(99, 102, 241, 0.5); }
}
.tracker-glow { animation: trackerGlow 2.4s ease-in-out infinite; }
@keyframes trackerBreathe {
  0%, 100% { filter: brightness(1); }
  50% { filter: brightness(1.25); }
}
.tracker-breathe { animation: trackerBreathe 3.2s ease-in-out infinite; }
.tracker-sweep { position: relative; overflow: hidden; }
.tracker-sweep::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(105deg, transparent 30%, rgba(255, 255, 255, 0.4) 50%, transparent 70%);
  transform: translateX(-120%);
  animation: trackerSweep 2.8s ease-in-out infinite;
  pointer-events: none;
}
@keyframes trackerSweep {
  0% { transform: translateX(-120%); }
  55%, 100% { transform: translateX(120%); }
}


@keyframes trackerBlink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}
.tracker-blink { animation: trackerBlink 1.8s ease-in-out infinite; }


@keyframes trackerRoll {
  0% { transform: rotateX(60deg) translateY(6px); opacity: 0; }
  100% { transform: rotateX(0deg) translateY(0); opacity: 1; }
}
.tracker-roll { animation: trackerRoll 380ms cubic-bezier(0.2, 0.8, 0.3, 1); transform-origin: 50% 100%; }
@keyframes trackerCelebrate {
  0%, 100% { filter: hue-rotate(0deg) brightness(1); }
  50% { filter: hue-rotate(90deg) brightness(1.15); }
}
.tracker-celebrate { animation: trackerCelebrate 1.6s ease-in-out infinite; }


/* ===== Time Tracker: accent-var backgrounds + extra animations ===== */
/* The pill sets --tracker-accent / --tracker-accent-soft / --tracker-accent-text
   inline from the resolved accent (named or custom hex), so every background
   works with the color wheel. */
.tracker-bg-glass {
  background: color-mix(in srgb, var(--tracker-accent, #6366f1) 12%, rgba(255,255,255,0.72));
  border: 1px solid color-mix(in srgb, var(--tracker-accent, #6366f1) 35%, transparent);
  backdrop-filter: blur(10px);
  color: var(--tracker-accent-text, #1e293b);
}
.tracker-bg-solid {
  background: var(--tracker-accent-soft, #eef2ff);
  border: 1px solid color-mix(in srgb, var(--tracker-accent, #6366f1) 30%, transparent);
  color: var(--tracker-accent-text, #1e293b);
}
.tracker-bg-outline {
  background: transparent;
  border: 1.5px solid var(--tracker-accent, #6366f1);
  color: var(--tracker-accent-text, #1e293b);
}
.tracker-bg-soft {
  background: color-mix(in srgb, var(--tracker-accent, #6366f1) 8%, transparent);
  border: 1px solid transparent;
  color: var(--tracker-accent-text, #1e293b);
}
.tracker-bg-accent {
  background: var(--tracker-accent, #6366f1);
  border: 1px solid var(--tracker-accent, #6366f1);
  color: #fff;
}
.tracker-bg-halo {
  background: var(--tracker-accent-soft, #eef2ff);
  border: 1px solid color-mix(in srgb, var(--tracker-accent, #6366f1) 45%, transparent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--tracker-accent, #6366f1) 18%, transparent), 0 0 18px color-mix(in srgb, var(--tracker-accent, #6366f1) 35%, transparent);
  color: var(--tracker-accent-text, #1e293b);
}
.tracker-bg-dotted {
  background: rgba(255,255,255,0.5);
  border: 2px dashed var(--tracker-accent, #6366f1);
  color: var(--tracker-accent-text, #1e293b);
}
.tracker-bg-striped {
  background: repeating-linear-gradient(45deg, color-mix(in srgb, var(--tracker-accent, #6366f1) 10%, transparent) 0 8px, transparent 8px 16px), var(--tracker-accent-soft, #eef2ff);
  border: 1px solid color-mix(in srgb, var(--tracker-accent, #6366f1) 30%, transparent);
  color: var(--tracker-accent-text, #1e293b);
}
.tracker-bg-elevated {
  background: #fff;
  border: 1px solid rgba(15,23,42,0.06);
  box-shadow: 0 8px 24px -6px color-mix(in srgb, var(--tracker-accent, #6366f1) 45%, rgba(0,0,0,0.25)), 0 2px 6px rgba(15,23,42,0.08);
  color: var(--tracker-accent-text, #1e293b);
}
.tracker-bg-inset {
  background: color-mix(in srgb, var(--tracker-accent, #6366f1) 9%, #f8fafc);
  border: 1px solid color-mix(in srgb, var(--tracker-accent, #6366f1) 22%, transparent);
  box-shadow: inset 0 2px 6px rgba(15,23,42,0.10);
  color: var(--tracker-accent-text, #1e293b);
}
.tracker-bg-neon {
  background: #0f172a;
  border: 1.5px solid var(--tracker-accent, #6366f1);
